import { Request, Response, NextFunction } from "express";
import crypto from "crypto";
import { UnauthorizedError } from "../Errors/unauthorizedError";

/**
 * 🔑 API-key guard for the public ecommerce integration endpoints.
 *
 * The key is the tenant key generated by Super Systego and stored in this
 * deployment's .env as SUPER_SYSTEGO_API_KEY.
 *
 * A dedicated ECOMMERCE_API_KEY can be set later if we want the ecommerce
 * integration to stop sharing the tenant's internal key. When it is not set,
 * the tenant key is used (current behaviour).
 */
const getConfiguredKey = (): string =>
  (process.env.ECOMMERCE_API_KEY || process.env.SUPER_SYSTEGO_API_KEY || "").trim();

export const ecommerceApiKey = (
  req: Request,
  _res: Response,
  next: NextFunction
): void => {
  try {
    const configuredKey = getConfiguredKey();

    if (!configuredKey) {
      throw new UnauthorizedError(
        "API key is not configured on the server",
        { code: "API_KEY_NOT_CONFIGURED" }
      );
    }

    const providedKey = String(req.headers["x-api-key"] || "").trim();

    if (!providedKey) {
      throw new UnauthorizedError("Missing X-API-KEY header", {
        code: "API_KEY_MISSING",
      });
    }

    const provided = Buffer.from(providedKey);
    const configured = Buffer.from(configuredKey);

    // timingSafeEqual throws when lengths differ, so check first.
    if (
      provided.length !== configured.length ||
      !crypto.timingSafeEqual(provided, configured)
    ) {
      throw new UnauthorizedError("Invalid API key", {
        code: "API_KEY_INVALID",
      });
    }

    next();
  } catch (error) {
    next(error);
  }
};

export default ecommerceApiKey;
